// #6a993d77a00f8f2a4a0d5e8a — פיתוח: הגדרת הפרטים הכלליים של הסימולציה (F-11, S-08 шаг 1). Кейсы SIM-001…SIM-006.
// Роль: business (testim), сохранённая сессия, без пароля. Десктоп 1440×900 (экраны бизнеса — только десктоп, L-20261014-5).
// Данные: черновик «QA-AUTO-0d5e8a-<stamp>» (טיוטה, неудаляем — удаление только с «да» пользователя);
// SIM-005 при наличии активной QA-симуляции создаёт (или открывает уже существующую) черновую версию N+1 — НЕ утверждает,
// число активных симуляций не меняется. Генерация AI, утверждение, /admin/providers, квоты — не трогаются.
import { test, expect } from '@playwright/test';
import { openWithApi, runStamp, Api } from '../support/api';
import { field, fillGeneral, nextStep, currentStep, createDraftViaStep1, simById } from '../support/simulation-editor';

test.use({ storageState: '../auth/business.json' });
test.describe.configure({ mode: 'serial' });

const STAMP = runStamp();
const DRAFT_NAME = `QA-AUTO-0d5e8a-${STAMP}`;
const TAG = '#6a993d77a00f8f2a4a0d5e8a';
let draftId = '';

/** Подсказка под пустым полем (источник: S-08 «טופס חדש מציג הסבר לכל קבוצת שדות»; FL-11 шаг 2). */
const HINTS: Record<string, string> = {
  name: 'שם לזיהוי הסימולציה ברשימת הסימולציות של העסק.',
  role_title: 'המשרה שאליה מגייסים. המועמד רואה אותה במסך הפתיחה.',
  industry: 'התחום שבו העסק פועל, למשל ביטוח, נדל״ן או ציוד משרדי.',
  product_or_service: 'מה המועמד מוכר בשיחה. מוצג לו במסך הפתיחה.',
  target_audience: 'למי העסק מוכר: סוג הלקוחות שהשיחה מדמה.',
  call_goal: 'המטרה שעל המועמד להשיג. היא זהה לכל המועמדים לאותה משרה.',
  customer_type: 'הקשר של הלקוח עם העסק כשהשיחה מתחילה.',
  language: 'נעולה על שפת ברירת המחדל של העסק.',
  duration_minutes: 'בין 5 ל-20 דקות. ברירת המחדל היא 7 דקות — המשך המומלץ לפיילוט.',
  desired_outcome: 'מה נחשב הצלחה בשיחה. התוצאה נקשרת לצעד הבא שנבחר.',
};

test.describe(`Редактор симуляции — шаг 1 «פרטים כלליים» (${TAG})`, () => {
  test(`шаг 1: 10 полей с подсказкой под каждым пустым, 7 мин по умолчанию (5…20), язык заблокирован на иврите @desktop @prod-safe ${TAG}`, async ({ page }) => {
    await page.goto('/simulations/new?start=scratch');
    await expect(currentStep(page, 'general')).toBeVisible();

    for (const [name, hint] of Object.entries(HINTS)) {
      const control = field(page, name);
      await expect(control, `поле ${name}`).toBeVisible();
      // Подсказка привязана к полю (aria-describedby) и видна под ним.
      const hintId = await control.getAttribute('aria-describedby');
      expect(hintId, `у поля ${name} нет подсказки`).toBeTruthy();
      await expect(page.locator(`[id="${hintId}"]`)).toHaveText(hint);
    }

    // AC3 / треб.3: 7 по умолчанию, диапазон 5…20.
    const duration = field(page, 'duration_minutes');
    await expect(duration).toHaveValue('7');
    await expect(duration.locator('option:checked')).toHaveText('7 דקות');
    const values = await duration.locator('option').evaluateAll((os) => os.map((o) => (o as HTMLOptionElement).value));
    expect(values).toEqual(Array.from({ length: 16 }, (_, i) => String(5 + i)));

    // AC5 / треб.4: язык из языка бизнеса (иврит), без выбора.
    const language = field(page, 'language');
    await expect(language).toBeDisabled();
    await expect(language).toHaveValue('he');
    await expect(language.locator('option')).toHaveCount(1);
  });

  test(`пустые обязательные поля: переход на шаг 2 закрыт, поля помечены, введённое сохраняется @desktop @prod-safe ${TAG}`, async ({ page }) => {
    await page.goto('/simulations/new?start=scratch');
    let saveCalls = 0;
    page.on('request', (r) => { if (r.url().includes('/rpc/save_simulation')) saveCalls += 1; });

    await field(page, 'name').fill(DRAFT_NAME);
    await field(page, 'role_title').fill('נציג/ת מכירות QA-AUTO');
    await page.getByRole('button', { name: 'הבא: לקוח וחשיפה' }).click();

    // AC2: переход закрыт, сводка недостающего (6: תחום, מוצר, קהל, מטרה, סוג לקוח, תוצאה).
    await expect(page.getByText('אי אפשר לעבור לשלב 2 — 6 דברים חסרים')).toBeVisible();
    for (const [name, label] of [
      ['industry', 'תחום הפעילות'],
      ['product_or_service', 'המוצר או השירות'],
      ['target_audience', 'קהל היעד'],
      ['call_goal', 'מטרת השיחה'],
      ['customer_type', 'סוג הלקוח'],
      ['desired_outcome', 'התוצאה הרצויה'],
    ]) {
      await expect(field(page, name), `поле ${name}`).toHaveAttribute('aria-invalid', 'true');
      await expect(page.locator(`#simulation-${name}-error`)).toHaveText(`יש למלא: ${label}`);
    }
    // Значения сохранены, шаг прежний, сервер не вызывался.
    await expect(field(page, 'name')).toHaveValue(DRAFT_NAME);
    await expect(field(page, 'role_title')).toHaveValue('נציג/ת מכירות QA-AUTO');
    await expect(currentStep(page, 'general')).toBeVisible();
    await expect(page).toHaveURL(/\/simulations\/new/);
    expect(saveCalls).toBe(0);
  });

  test(`«הבא» сохраняет черновик (draft, v1, he, 7 мин) и открывает шаг 2 @desktop @data ${TAG}`, async ({ page }) => {
    const saved = await createDraftViaStep1(page, DRAFT_NAME);
    // AC1: сохраняется טיוטה и показан следующий шаг.
    expect(saved).toMatchObject({ status: 'draft', version: 1 });
    draftId = saved.id;
    test.info().annotations.push({ type: 'test-data', description: `simulation ${DRAFT_NAME} ${draftId} (draft, неудаляем)` });
    await expect(page).toHaveURL(new RegExp(`/simulations/${draftId}`));

    const api = await openWithApi(page, `/simulations/${draftId}`);
    const row = await simById(api, draftId);
    expect(row).toMatchObject({ name: DRAFT_NAME, status: 'draft', language: 'he', duration_minutes: 7 });

    // После перезагрузки значения шага 1 на месте.
    await page.getByRole('button', { name: /פרטים כלליים/ }).first().click();
    await expect(field(page, 'name')).toHaveValue(DRAFT_NAME);
    await expect(field(page, 'industry')).toHaveValue('אנרגיה סולארית');
  });

  test(`сервер не принимает язык, отличный от языка бизнеса: language "en" → 400 language_not_enabled @desktop @data ${TAG}`, async ({ page }) => {
    expect(draftId, 'нужен черновик из предыдущего теста (serial)').toBeTruthy();
    const api = await openWithApi(page, `/simulations/${draftId}`);
    const res = await api.rpc('save_simulation', { p_simulation_id: draftId, p_fields: { language: 'en' } });
    // AC5 / реджект rej_1791198797112 п.1.
    expect(res.status()).toBe(400);
    expect(await res.text()).toContain('language_not_enabled');
    expect((await simById(api, draftId)).language).toBe('he');
  });

  test(`правка активной версии: предупреждение и новая черновая версия, активная не меняется @desktop @data ${TAG}`, async ({ page }) => {
    const api = await openWithApi(page, '/simulations');
    const list = await api.get('simulations?select=id,name,version,lineage_id,status,end_conditions&status=eq.active&name=ilike.QA*&order=updated_at.desc&limit=1');
    expect(list.ok()).toBeTruthy();
    const [active] = (await list.json()) as { id: string; name: string; version: number; lineage_id: string; end_conditions: string | null }[];
    test.skip(!active, 'у testim нет активной QA-симуляции — AC4 без утверждения не проверить (утверждение запрещено)');

    await page.goto(`/simulations/${active.id}`);
    // AC4: предупреждение о правке активной версии.
    await expect(page.getByText('עריכה של גרסה פעילה')).toBeVisible();
    await expect(page.getByText('שינוי יישמר כגרסה חדשה בטיוטה. הגרסה הפעילה ממשיכה לשמש את המועמדים עד שהגרסה החדשה תאושר.')).toBeVisible();

    const end = field(page, 'end_conditions');
    await end.fill(`${active.end_conditions ?? ''} QA-AUTO-0d5e8a-${STAMP}`.trim());
    const res = await nextStep(page, 'לקוח וחשיפה');

    if (res.status() === 200) {
      const body = (await res.json()) as { id: string; status: string; version: number; lineage_id: string };
      expect(body.id).not.toBe(active.id);
      expect(body).toMatchObject({ status: 'draft', version: active.version + 1, lineage_id: active.lineage_id });
      await expect(page.getByText(`נוצרה גרסה ${active.version + 1} כטיוטה`)).toBeVisible();
      test.info().annotations.push({ type: 'test-data', description: `version ${body.version} draft ${body.id} of ${active.name} (не утверждается)` });
    } else {
      // Черновая версия уже есть (прошлый прогон / ручная проверка) — редактор открывает её, а не создаёт вторую.
      expect(await res.text()).toContain('newer_version_exists');
      await expect(page.getByText('העריכה ממשיכה בטיוטה הקיימת')).toBeVisible();
      await expect(page).not.toHaveURL(new RegExp(`/simulations/${active.id}(\\?|$)`));
    }

    // Треб.6: активная версия прежняя — статус, номер, поля.
    const after = await simById(api, active.id);
    expect(after).toMatchObject({ status: 'active', version: active.version, end_conditions: active.end_conditions });
  });

  test(`прежняя версия в списке: «הדוחות נשארים משויכים לגרסה N» @desktop @prod-safe ${TAG}`, async ({ page }) => {
    const api: Api = await openWithApi(page, '/simulations');
    const res = await api.get('simulations?select=id,name,version&status=eq.previous_version&order=updated_at.desc&limit=1');
    expect(res.ok()).toBeTruthy();
    const [prev] = (await res.json()) as { id: string; name: string; version: number }[];
    test.skip(!prev, 'у testim нет версии в статусе previous_version');
    // AC4: предыдущая версия сохраняется как «גרסה קודמת», отчёты остаются привязаны к ней.
    await page.goto('/simulations');
    await expect(page.getByText(`הדוחות נשארים משויכים לגרסה ${prev.version}`).first()).toBeVisible();
  });
});
